// n8n Code Node: Combine All Documents
const dataArray = $input.all();

const SEPARATOR = '\n\n--- DOCUMENT SEPARATOR ---\n\n';
const MAX_CHUNK_SIZE = 250000; // така ж межа, як у Chunk Splitter

let combinedText = '';
let totalLength = 0;

dataArray.forEach((item, index) => {
  const text = item.json?.content || item.content || '';
  if (text.trim().length > 0) {
    combinedText += text.trim() + SEPARATOR;
    totalLength += text.length;
  }
  console.log(`Item ${index + 1}: ${text.length} chars`);
});

const estimatedChunks = Math.ceil(totalLength / MAX_CHUNK_SIZE);

console.log('Total combined content length:', totalLength);
console.log('Estimated total chunks:', estimatedChunks);

return [{
  json: {
    combinedContent: combinedText.trim(),
    totalDocuments: dataArray.length,
    totalLength: totalLength,
    maxChunkSize: MAX_CHUNK_SIZE,
    totalChunks: estimatedChunks
  }
}];

// n8n Code Node: Chunk Splitter (fixed)
const input = $input.item.json;
const allContent = input.combinedContent || '';
const SEPARATOR = '--- DOCUMENT SEPARATOR ---';
const MAX_CHUNK_SIZE = input.maxChunkSize || 250000;

let chunks = [];
let startIndex = 0;
let chunkIndex = 0;

function addChunkToArray(chunkText, index) {
  const trimmed = chunkText.trim();
  if (trimmed.length === 0) return;
  chunks.push({
    json: {
      chunkIndex: index + 1,
      // totalChunks буде встановлено після розбиття
      chunkContent: trimmed,
      estimatedTokens: Math.ceil(trimmed.length / 4)
    }
  });
}

while (startIndex < allContent.length) {
  let endIndex = Math.min(startIndex + MAX_CHUNK_SIZE, allContent.length);

  // Якщо є розділювачі — розумне відсікання по SEPARATOR
  if (endIndex < allContent.length) {
    const separatorIndex = allContent.lastIndexOf(SEPARATOR, endIndex);
    // якщо знайшли розділювач в межах поточного блоку (після startIndex)
    if (separatorIndex > startIndex) {
      endIndex = separatorIndex + SEPARATOR.length;
    }
  }

  const chunkText = allContent.slice(startIndex, endIndex);
  addChunkToArray(chunkText, chunkIndex);

  startIndex = endIndex;
  chunkIndex++;
}

// Тепер, коли всі chunks зібрані, встановлюємо totalChunks у кожен елемент
const totalChunks = chunks.length;
const result = chunks.map(item => {
  return {
    json: {
      ...item.json,
      totalChunks
    }
  };
});

console.log(`✅ Created ${result.length} chunks from ${input.totalDocuments || 'unknown'} documents`);
console.log('Total chars:', allContent.length);
console.log(`🎯 Estimated total tokens: ${Math.ceil(allContent.length / 4).toLocaleString()}`);

return result;

// n8n Code Node: Single Chunk Extractor

const inputData = $input.first().json;

// Якщо дані приходять із попереднього вузла
const chunks = inputData.chunks || [];
const chunkIndex = inputData.currentItemIndex || 0;
const totalChunks = inputData.totalChunks || inputData.totalItems || 1;

let chunkContent = '';

try {
  if (chunks.length > 0 && chunks[chunkIndex]) {
    const currentChunk = chunks[chunkIndex];

    // Варіант 1: структура [{ content: "..."}]
    if (Array.isArray(currentChunk) && currentChunk.length > 0) {
      const firstItem = currentChunk[0];
      chunkContent = firstItem?.content || firstItem?.json?.content || '';
    }
    // Варіант 2: структура без вкладення
    else if (currentChunk.content) {
      chunkContent = currentChunk.content;
    }
  } else if (inputData.combinedContent) {
    // Якщо немає chunks, але є combinedContent (один великий документ)
    chunkContent = inputData.combinedContent;
  }
} catch (error) {
  console.error('Error processing chunk:', error);
  chunkContent = '⚠️ Error processing chunk content';
}

console.log(`📄 Single chunk content length: ${chunkContent.length} chars`);

return {
  chunkContent,
  chunkIndex: chunkIndex + 1,
  totalChunks,
  processingType: "final"
};

// Функція перевірки, чи це "обгорнутий" JSON
function needsParsing(obj) {
    return obj && obj.action === "parse" && typeof obj.text === "string";
}

// Функція для парсингу тексту з Markdown
function parseTextWithMarkdown(text) {
    text = text.replace(/```json\s*|```/g, "").trim();
    try {
        let parsed = JSON.parse(text);
        return parsed.output;
    } catch (err) {
        throw new Error("Неможливо розпізнати JSON після очищення Markdown");
    }
}

// Обробляємо всі items
return $input.all().map(item => {
    const output = item.json;

    if (needsParsing(output)) {
        return parseTextWithMarkdown(output.text);
    }

    // Якщо формат вже правильний
    return output;
});

// Обробляємо всі items
const items = $input.all().map(item => {
    const jsonData = item.json;

    // Пропускаємо items з помилкою
    if (jsonData.error === "Bad request - please check your parameters") {
        return null; // Пропускаємо цей item
    }

    // Якщо це дані з output, повертаємо їх
    if (jsonData.output && typeof jsonData.output === 'object' && jsonData.output !== null) {
        return {
            json: jsonData.output
        };
    }

    // Якщо це потрібно парсити
    if (jsonData.action === "parse" && typeof jsonData.text === "string") {
        const text = jsonData.text.replace(/```json\s*|```/g, "").trim();
        try {
            const parsed = JSON.parse(text);
            if (parsed.output && typeof parsed.output === 'object' && parsed.output !== null) {
                return {
                    json: parsed.output
                };
            }
        } catch (err) {
            // Якщо парсинг не вдався
        }
    }

    // Якщо output не об'єкт або його немає, повертаємо безпечний об'єкт
    if (jsonData.output) {
        return {
            json: { value: jsonData.output }
        };
    }

    // Якщо нічого не підійшло, повертаємо оригінальні дані
    return {
        json: jsonData
    };
});

// Фільтруємо null values (пропущені items)
return items.filter(item => item !== null);

// 1. Отримуємо глобальні дані (об’єкт)
const workflowStaticData = $getWorkflowStaticData('global');

// 2. Ініціалізація лічильника, якщо він ще не існує
